#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    while (!v.empty()) {
        cout << v.back() << endl;
        v.pop_back();
    }

    cout << v.empty() << endl;
    return 0;
}
